-- คอมไพล์ task_d60b3f0310094ab3bdbbad1eca43e81e_050100_append_ss_esim_valid.sql กับฐานจริงแบบไม่ดึงข้อมูล (WHERE 1=0) · SELECT อย่างเดียว
SELECT * FROM (
SELECT CAST(TO_CHAR(first_installed, 'YYYYMMDD') AS NUMBER) AS partition_date ,cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cp_id ,service_id ,before_sharing ,price_rate_type ,network_type ,invoicing_co_id ,share_basis ,cdr_filename ,chk_duplicate ,filter_dtm ,create_by ,remap_dtm ,remap_by ,process_date ,transaction_units ,status ,workflow_process_date,file_date FROM ( SELECT cdr_id ,cdr_type ,partner ,owner ,iccid ,first_installed ,profile_type ,eid ,sim_type ,cp_id ,service_id ,null as before_sharing ,price_rate_type ,network_type ,invoicing_co_id ,share_basis ,cdr_filename ,chk_duplicate ,filter_dtm ,create_by ,null as remap_dtm ,null as remap_by ,SYSDATE as process_date ,'1' as transaction_units ,status ,workflow_process_date, file_date FROM DSSDEV.tb_staging_ss_esim_raw_temp CROSS JOIN ( SELECT COUNT(*) AS chk_dup_append FROM DSSDEV.tb_transaction_ss_esim_valid WHERE status = 'MAP' AND workflow_process_date = (SELECT workflow_process_date FROM DSSDEV.tb_staging_ss_esim_landing_to_discovery_workflow_status) ) WHERE status = 'MAP' AND chk_dup_append = 0 )
) WHERE 1=0
